use op15_adaptive_harness::{action::{Action,ActionState}, permissions::{Capability,PermissionSet}};
#[test] fn denied_capability_cannot_be_approved() { let permissions = PermissionSet(vec![]); let mut action = Action { id:"a".into(), capability:"write".into(), scope:"repo".into(), risk:1, state:ActionState::Proposed }; assert!(!permissions.allows("write","repo",1)); assert!(action.approve(false).is_err()); assert_eq!(action.state,ActionState::Failed); }
#[test] fn effect_requires_confirmed_transition_path() { let mut action = Action { id:"a".into(), capability:"read".into(), scope:"repo".into(), risk:0, state:ActionState::Proposed }; action.approve(true).unwrap(); action.start().unwrap(); action.effect_applied().unwrap(); action.confirm(true).unwrap(); assert_eq!(action.state,ActionState::Confirmed); }
#[test] fn capability_scope_is_exact() { let p = PermissionSet(vec![Capability{name:"read".into(),scope:"repo".into(),risk:0}]); assert!(p.allows("read","repo",0)); assert!(!p.allows("read","other",0)); }
